import os
import sqlite3
import secrets
from functools import wraps

from flask import Flask, request, jsonify, g
from passlib.hash import pbkdf2_sha256

APP_SECRET = os.environ.get("APP_SECRET", "dev-secret-change-me")
DB_PATH = "db.sqlite3"

app = Flask(__name__)
app.config["SECRET_KEY"] = APP_SECRET


def get_db():
    if "db" not in g:
        g.db = sqlite3.connect(DB_PATH)
        g.db.row_factory = sqlite3.Row
        g.db.execute("PRAGMA foreign_keys = ON")
    return g.db


@app.teardown_appcontext
def close_db(exception=None):
    db = g.pop("db", None)
    if db is not None:
        db.close()


def init_db():
    conn = sqlite3.connect(DB_PATH)
    try:
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS invitations (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                email TEXT NOT NULL UNIQUE,
                invite_id TEXT NOT NULL UNIQUE,
                created_at TEXT NOT NULL DEFAULT (datetime('now'))
            )
            """
        )
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS users (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_name TEXT NOT NULL UNIQUE,
                password_hash TEXT NOT NULL,
                email TEXT,
                invite_id TEXT,
                created_at TEXT NOT NULL DEFAULT (datetime('now'))
            )
            """
        )
        conn.commit()
    finally:
        conn.close()


def error(message, status):
    return jsonify({"message": message}), status


@app.route("/invite_user", methods=["POST"])
def invite_user():
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return error("Invalid request body", 400)

    email = data.get("email")
    if not isinstance(email, str) or not email.strip():
        return error("Invalid email", 400)

    email = email.strip().lower()

    db = get_db()
    row = db.execute(
        "SELECT invite_id FROM invitations WHERE email = ?", (email,)
    ).fetchone()

    if row is not None:
        invite_id = row["invite_id"]
        message = "Invitation already exists for this email."
    else:
        invite_id = secrets.token_urlsafe(24)
        try:
            db.execute(
                "INSERT INTO invitations (email, invite_id) VALUES (?, ?)",
                (email, invite_id),
            )
            db.commit()
        except sqlite3.IntegrityError:
            row = db.execute(
                "SELECT invite_id FROM invitations WHERE email = ?", (email,)
            ).fetchone()
            if row is None:
                return error("Could not create invitation", 500)
            invite_id = row["invite_id"]
        message = "Invitation created."

    return jsonify({"invite_id": invite_id, "message": message}), 200


@app.route("/create_user", methods=["POST"])
def create_user():
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return error("Invalid request body", 400)

    invite_id = data.get("invite_id")
    user_name = data.get("user_name")
    password = data.get("password")

    if not isinstance(invite_id, str) or not invite_id.strip():
        return error("Invalid invite_id", 401)
    if not isinstance(user_name, str) or not user_name.strip():
        return error("Invalid user_name", 400)
    if not isinstance(password, str) or not password:
        return error("Invalid password", 400)

    invite_id = invite_id.strip()
    user_name = user_name.strip()

    db = get_db()

    invitation = db.execute(
        "SELECT email FROM invitations WHERE invite_id = ?", (invite_id,)
    ).fetchone()
    if invitation is None:
        return error("Invalid invite_id", 401)

    existing = db.execute(
        "SELECT id FROM users WHERE user_name = ?", (user_name,)
    ).fetchone()
    if existing is not None:
        return error(
            "Username already exists. Try providing different username.", 400
        )

    password_hash = pbkdf2_sha256.hash(password)

    try:
        db.execute(
            "INSERT INTO users (user_name, password_hash, email, invite_id) "
            "VALUES (?, ?, ?, ?)",
            (user_name, password_hash, invitation["email"], invite_id),
        )
        db.commit()
    except sqlite3.IntegrityError:
        return error(
            "Username already exists. Try providing different username.", 400
        )

    return jsonify({"message": "User created"}), 200


init_db()

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000)
